arguments.command:
python3 -I - <<'PYEOF'
import json
B='/user/user1/autorlbench-runs/20261126095528-80794-453b/workspace/generation_records/'
d=json.load(open(B+'engine-requests.json'))
print('budget:', d['response_budget'])
for r in d['requests']:
    print('---')
    for k in ('question_id','answer','finish_reason','stop_reason'):
        print(k,'=',r.get(k))
    print('prompt_len', len(r['prompt_token_ids']))
    print('resp_len', len(r['token_ids']))
    print('prompt first 8', r['prompt_token_ids'][:8])
    print('prompt last 6', r['prompt_token_ids'][-6:])
    print('resp last 6 ids', r['token_ids'][-6:])
    print('resp last 6 lps', [round(x,8) for x in r['log_probs'][-6:]])
    lp=r['log_probs']
    print('mean lp', round(sum(lp)/len(lp),4), 'frac>-0.01', round(sum(1 for x in lp if x>-0.01)/len(lp),3))
    print('n token 11 in resp', sum(1 for t in r['token_ids'] if t==11))
    print('n token 11 in prompt', sum(1 for t in r['prompt_token_ids'] if t==11))
print()
print('== heldout ==')
h=json.load(open(B+'heldout-responses.json'))
for k,v in h.items():
    if k!='samples': print(k,'=',repr(v)[:200])
for i,s in enumerate(h['samples']):
    print('-- sample',i)
    if isinstance(s,dict):
        for kk,vv in s.items():
            if isinstance(vv,str): print(' ',kk,': str len',len(vv),repr(vv[:120]))
            elif isinstance(vv,list): print(' ',kk,': list len',len(vv),vv[:5])
            else: print(' ',kk,'=',vv)
    else: print(repr(s)[:300])
PYEOF

