arguments.command:
python3 -I - <<'PYEOF'
import json
B='/user/user1/autorlbench-runs/20261126095528-80794-453b/workspace/experiment_logs/'
for f in ['validation/0.jsonl','validation/1.jsonl','validation/2.jsonl','rollouts/1.gen_001.jsonl','rollouts/2.gen_001.jsonl']:
    print('=====',f)
    with open(B+f) as fh:
        lines=fh.readlines()
    print('records:',len(lines))
    r=json.loads(lines[0])
    print('keys:',list(r.keys()))
    for i,l in enumerate(lines):
        d=json.loads(l)
        summary={}
        for k,v in d.items():
            if isinstance(v,str): summary[k]=('str len %d'%len(v), v[:60].replace('\n',' '))
            elif isinstance(v,list): summary[k]=('list len %d'%len(v), v[:6])
            elif isinstance(v,dict): summary[k]=list(v.keys())
            else: summary[k]=v
        print(i, summary)
        if i>=8: break
PYEOF

